-- Seed: video templates from bagege.cn template plaza (30 templates)
-- Categories first, then templates. All idempotent.


SET @fashion_id = (SELECT id FROM template_categories WHERE category_key='fashion_video' LIMIT 1);
SET @ecommerce_id = (SELECT id FROM template_categories WHERE category_key='ecommerce_video' LIMIT 1);
SET @food_id = (SELECT id FROM template_categories WHERE category_key='food_video' LIMIT 1);
SET @restaurant_id = (SELECT id FROM template_categories WHERE category_key='restaurant_video' LIMIT 1);

